// The question bank (~1.3 MB) and the word list load only when a page needs them,
// so the home page opens without them. Topic names and counts for every page come
// from data/questions/meta.js (small, generated by `npm run sync`).
// sw.js still keeps both files on the phone for offline use.
import { pruneMissing } from './store.js';

let bank = null;
let bankLoading = null;
let vocab = null;
let vocabLoading = null;

/** The bank module ({ QUESTIONS, QUESTION_MAP, inTopic, … }) once loaded, else null. */
export const getBank = () => bank;
export function loadBank() {
  bankLoading ||= import('../../../data/questions/index.js').then(m => {
    bank = m;
    pruneMissing(m.QUESTION_MAP);
    return m;
  }).catch(err => { bankLoading = null; throw err; });
  return bankLoading;
}

export const getVocab = () => vocab;
export function loadVocab() {
  vocabLoading ||= import('../../../data/vocabulary.js').then(m => (vocab = m.default)).catch(err => { vocabLoading = null; throw err; });
  return vocabLoading;
}

/** Load both in the background once the page is idle, so later pages open at once. */
export function prefetchData() {
  const go = () => loadBank().then(loadVocab).catch(() => {});
  if ('requestIdleCallback' in window) requestIdleCallback(go, { timeout: 4000 });
  else setTimeout(go, 1500);
}
